// Regenerates apps/web/src/i18n/registry.ts from the namespace files in i18n/vi and i18n/en.
// Run after adding a namespace: node scripts/i18n-registry.mjs
import { readdirSync, writeFileSync, existsSync } from "node:fs";

const DIR = "apps/web/src/i18n";
const names = readdirSync(`${DIR}/vi`)
  .filter((f) => f.endsWith(".ts"))
  .map((f) => f.slice(0, -3))
  .sort();
for (const n of names) {
  if (!existsSync(`${DIR}/en/${n}.ts`)) throw new Error(`missing en/${n}.ts`);
}
const id = (n) => n.replace(/[^A-Za-z0-9]/g, "_");
const lines = [
  "// GENERATED by scripts/i18n-registry.mjs — do not edit by hand.",
  ...names.map((n) => `import vi_${id(n)} from "./vi/${n}";`),
  ...names.map((n) => `import en_${id(n)} from "./en/${n}";`),
  "",
  `export const VI = {\n${names.map((n) => `  ${JSON.stringify(n)}: vi_${id(n)},`).join("\n")}\n};`,
  "",
  "/** Every English namespace must carry exactly the Vietnamese keys. */",
  `export const EN: { [N in keyof typeof VI]: Record<keyof (typeof VI)[N], string> } = {\n${names
    .map((n) => `  ${JSON.stringify(n)}: en_${id(n)},`)
    .join("\n")}\n};`,
  "",
];
writeFileSync(`${DIR}/registry.ts`, lines.join("\n"));
console.log(`i18n registry: ${names.length} namespaces`);
